import { Memo } from "@/types/proto/api/v1/memo_service";
export async function loadMemos(): Promise<Memo[]> {
  const response = await fetch(new URLSearchParams(location.search).get("memo") ? "/api/v1/" + validMemoName(new URLSearchParams(location.search).get("memo")!) : "/api/v1/memos?pageSize=100");
  if (!response.ok) throw new Error(response.status===404 ? "Memo not found" : "Memos unavailable");
  const data = await response.json();
  return (data.memos || (data.name ? [data] : [])).map((memo: unknown) => Memo.fromPartial({ ...(memo as Memo), displayTime: (memo as Memo).displayTime ? new Date(String((memo as Memo).displayTime)) : undefined }));
}
export function selectMemos(memos: Memo[], _params: URLSearchParams): Memo[] { return memos; }

function validMemoName(name:string):string { if(!/^memos\/[a-zA-Z0-9_-]+$/.test(name)) throw new Error("Memo not found"); return name; }

