"""Validate snapshots before the database performs its single write."""
import json
def encode(data):
    return json.dumps(data, sort_keys=True)
def decode(text):
    try: data=json.loads(text)
    except (TypeError, ValueError) as exc: raise ValueError("Invalid snapshot") from exc
    if not isinstance(data,dict): raise ValueError("Expected tables object")
    for name,table in data.items():
        if not isinstance(name,str) or not isinstance(table,dict): raise ValueError("Invalid table")
        for key,document in table.items():
            if not key.isascii() or not key.isdigit() or str(int(key))!=key or int(key)<1 or not isinstance(document,dict): raise ValueError("Invalid document")
    return data
